using UnityEngine;

namespace Astrea.BattleActions;

public class GainSandsOfTimeBasedAction : BattleAction
{
	[Header("Rewind")]
	[SerializeField]
	private DefaultEffectAction gainSandsOfTimeEffectAction;

	public DefaultEffectAction GainSandsOfTimeEffectAction => gainSandsOfTimeEffectAction;

	public virtual int GetSandsOfTimeAmount(int amount = 0)
	{
		return 0;
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		PlaySFX();
		SpawnVFXOnPlayerPosition(4f);
		gainSandsOfTimeEffectAction.CastTargetAmount(target, GetSandsOfTimeAmount(), source);
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		PlaySFX();
		SpawnVFXOnPlayerPosition(4f);
		gainSandsOfTimeEffectAction.CastTargetAmount(target, GetSandsOfTimeAmount(amount), source);
	}
}
